// Shared navigation; no asset, storage, playback or routing mutations.
(async()=>{
 if(document.querySelector('cat-lab-menu'))return;
 const floating=document.currentScript.dataset.workshopNav==='floating',source=document.currentScript.src,{workshopGroups,resolveWorkshopTools,currentWorkshopTool,matchesWorkshopTool}=await import(new URL('workshop-tools.js',source));
 if(document.querySelector('cat-lab-menu'))return;
 const isStudio=document.title==='Cat Frame Studio',studio=isStudio?location.href.split('#')[0]:'http://127.0.0.1:8767/',tools=resolveWorkshopTools(studio,'http://127.0.0.1:8769/');
 const host=document.createElement('cat-lab-menu'),root=host.attachShadow({mode:'open'});
 if(floating)host.setAttribute('floating','');
 root.innerHTML=`<style>
 :host{display:block;position:relative;z-index:100;font:13px/1.45 system-ui;color:#e1e9eb}*{box-sizing:border-box}[hidden]{display:none!important}nav{display:flex;align-items:center;gap:20px;padding:8px 22px;background:#111c24;border-bottom:1px solid #354750;min-height:56px}.brand{min-width:145px;text-decoration:none;color:#b9c7cd}.brand strong{display:block;font-size:11px;letter-spacing:.1em}.where{display:block;font-size:11px;color:#c8dfa9;margin-top:2px}.groups{display:flex;align-items:center;gap:4px;flex:1}a,button,summary{-webkit-tap-highlight-color:transparent}button,summary{font:inherit;color:inherit;background:transparent;border:1px solid transparent;border-radius:6px;padding:7px 11px;cursor:pointer}button:hover,summary:hover,a.tool:hover{background:#293b43}button:focus-visible,summary:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid #c3dda7;outline-offset:2px}.all-tools{border-color:#516353;color:#d6e8bd;white-space:nowrap}details{position:relative}summary{list-style:none;white-space:nowrap}summary::-webkit-details-marker{display:none}summary::after{content:' ▾';color:#92a4ae}details.active>summary{color:#d7e9bc;background:#304332}details[open]>summary{background:#2a3d45}.dropdown{position:absolute;top:calc(100% + 9px);left:0;width:310px;padding:9px;background:#172831;border:1px solid #4b606b;border-radius:9px;box-shadow:0 10px 24px #0006;max-height:70vh;overflow:auto}.tool{display:block;text-decoration:none;color:#dfe9ec;padding:9px 11px;border-radius:6px}.tool strong{display:block;font-weight:560;font-size:13px}.tool small{display:block;color:#9eb3be;font-size:11px;line-height:1.5;margin-top:3px}.tool[aria-current=page]{background:#314934;color:#d5eabd}.tool[aria-current=page] strong::after{content:' · current';font-weight:400;font-size:10px}.group-note{color:#93aab6;font-size:11px;margin:3px 10px 8px}dialog{color:#e5eced;background:#14242d;border:1px solid #536a74;border-radius:14px;width:min(1120px,94vw);max-height:88vh;padding:0;box-shadow:0 24px 70px #0008}dialog::backdrop{background:#061119b8}.directory-head{position:sticky;top:0;background:#14242d;z-index:1;padding:20px 24px 14px;border-bottom:1px solid #354c56}.directory-title{display:flex;align-items:center;justify-content:space-between;gap:10px}h2{font-size:22px;letter-spacing:-.02em;margin:0}.close{border-color:#52646c}.directory-head p{color:#9fb4bf;font-size:12px;margin:6px 0 14px}label{display:block;font-size:11px;color:#aac0c9}input{display:block;width:100%;margin-top:5px;padding:10px 12px;border:1px solid #526b74;border-radius:7px;color:#e8efef;background:#0e1e27;font:14px system-ui}.results-count{font-size:11px;color:#bed6a8;margin-top:8px}.directory-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;padding:24px}.directory-group h3{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#d1e4b7;margin:0 0 5px}.directory-group>p{color:#99afb9;font-size:11px;margin:0 0 8px}.directory-group .tool{padding-left:0;padding-right:5px}.directory-group .tool:hover{padding-left:7px}.directory-foot{border-top:1px solid #354c56;padding:14px 24px;color:#9db3be;font-size:11px}.empty{padding:10px 24px;color:#c4d4db}
 :host([floating]){position:fixed;right:12px;bottom:12px}:host([floating]) nav{padding:5px;min-height:0;border:1px solid #4b606b;border-radius:9px;box-shadow:0 4px 16px #0005}:host([floating]) .brand,:host([floating]) .groups{display:none}
 @media(max-width:900px){nav{gap:10px;padding:8px 12px}.brand{min-width:115px}summary{padding:7px 8px}.dropdown{position:fixed;left:12px;top:calc(var(--cat-lab-menu-height,56px) + 5px);width:min(360px,calc(100vw - 24px))}.directory-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.groups{display:none}nav{justify-content:space-between}.brand{min-width:0}.where{max-width:230px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.directory-grid{grid-template-columns:1fr;padding:18px}.directory-head{padding:16px}.directory-foot{padding:14px 18px}dialog{width:95vw;max-height:92vh}}
 </style>`;
 const nav=document.createElement('nav');nav.setAttribute('aria-label','Cat workshop tools');const brand=document.createElement('a');brand.href=studio+'#sequences';brand.className='brand';const title=document.createElement('strong'),where=document.createElement('span');title.textContent='CAT WORKSHOP';where.className='where';brand.append(title,where);nav.append(brand);
 const groupBar=document.createElement('div');groupBar.className='groups';nav.append(groupBar);
 const directory=document.createElement('dialog');directory.setAttribute('aria-labelledby','tools-title');directory.innerHTML='<div class="directory-head"><div class="directory-title"><h2 id="tools-title">All tools</h2><button class="close" aria-label="Close tool directory">Close</button></div><p>Find an editor, a controlled experiment or a diagnostic fixture.</p><label>Search tools<input type="search" placeholder="Try particles, climbing, startup or gaze"></label><div class="results-count" role="status"></div></div><div class="directory-grid"></div><p class="empty" hidden>No tools match. Try a shorter search or another term.</p><div class="directory-foot">Drafts belong to their individual tools. Existing exports stay inside their editors. Animated GIF export is planned.</div>';
 const search=directory.querySelector('input'),grid=directory.querySelector('.directory-grid'),menus=[];
 const closeMenus=()=>menus.forEach(d=>d.open=false);
 function link(tool){const a=document.createElement('a');a.className='tool';a.href=tool.url;a.dataset.tool=tool.id;const name=document.createElement('strong'),description=document.createElement('small');name.textContent=tool.label;description.textContent=tool.description;a.append(name,description);a.onclick=()=>{closeMenus();if(directory.open)directory.close();};return a;}
 for(const group of workshopGroups){
  const members=tools.filter(t=>t.group===group.id),menu=document.createElement('details'),summary=document.createElement('summary'),dropdown=document.createElement('div');summary.textContent=group.label;dropdown.className='dropdown';const note=document.createElement('p');note.className='group-note';note.textContent=group.description;dropdown.append(note,...members.map(link));menu.append(summary,dropdown);groupBar.append(menu);menus.push(menu);menu.dataset.group=group.id;menu.addEventListener('toggle',()=>{if(menu.open)for(const other of menus)if(other!==menu)other.open=false;});
  const section=document.createElement('section');section.className='directory-group';section.dataset.group=group.id;const h=document.createElement('h3'),p=document.createElement('p');h.textContent=group.label;p.textContent=group.description;section.append(h,p,...members.map(link));grid.append(section);
 }
 const all=document.createElement('button');all.className='all-tools';all.textContent='All tools';all.setAttribute('aria-haspopup','dialog');nav.append(all);root.append(nav,directory);
 function filter(){let count=0;for(const section of grid.children){let shown=0;for(const a of section.querySelectorAll('a')){a.hidden=!matchesWorkshopTool(tools.find(t=>t.id===a.dataset.tool),search.value);if(!a.hidden)shown++;}section.hidden=!shown;count+=shown;}directory.querySelector('.results-count').textContent=count+' of '+tools.length+' tools';directory.querySelector('.empty').hidden=count>0;}
 all.onclick=()=>{closeMenus();search.value='';filter();directory.showModal();search.focus();};search.oninput=filter;directory.querySelector('.close').onclick=()=>directory.close();directory.addEventListener('close',()=>all.focus());
 function active(){const current=currentWorkshopTool(tools,location.href,isStudio);where.textContent=current?workshopGroups.find(g=>g.id===current.group).label+' / '+current.label:'Tools & experiments';for(const a of root.querySelectorAll('[data-tool]'))a.setAttribute('aria-current',a.dataset.tool===current?.id?'page':'false');for(const d of menus)d.classList.toggle('active',d.dataset.group===current?.group);}
 // Shadow DOM retargets key/paste events: never let Studio canvas shortcuts
 // process typing, arrows, Space or pasted search text from this navigation.
 root.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'){e.preventDefault();if(directory.open)directory.close();else {const open=menus.find(d=>d.open);closeMenus();open?.querySelector('summary').focus();}}});root.addEventListener('paste',e=>e.stopPropagation());
 document.addEventListener('click',e=>{if(!e.composedPath().includes(host))closeMenus();});if(floating)document.body.append(host);else document.body.prepend(host);if(isStudio)document.body.classList.add('cat-workshop-nav-ready');active();window.addEventListener('hashchange',active);
 if(!floating)new ResizeObserver(()=>document.documentElement.style.setProperty('--cat-lab-menu-height',host.getBoundingClientRect().height+'px')).observe(host);
})().catch(error=>console.warn('Workshop navigation unavailable; existing page controls retained.',error.message));
